import{_ as n,a0 as o,w as s,s as p,ao as d,I as l,x as a,a1 as i,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"5 分钟内了解 OSI 模型 | LCTT x X-CMD","titleTemplate":false,"description":"5 分钟内了解 OSI 模型 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 分钟内了解 OSI 模型 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 分钟内了解 OSI 模型 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221004 Learn the OSI model in 5 minutes","title":"5 分钟内了解 OSI 模型","tag":"202212","desc":""},"relativePath":"202212/20221004 Learn the OSI model in 5 minutes.md","filePath":"[post].md"}'),m={name:"202212/20221004 Learn the OSI model in 5 minutes.md"};function h(u,e,f,b,I,S){const t=o("Link");return s(),p("div",null,[e[15]||(e[15]=d('<h1 id="_5-分钟内了解-osi-模型" tabindex="-1">5 分钟内了解 OSI 模型 <a class="header-anchor" href="#_5-分钟内了解-osi-模型" aria-label="Permalink to “5 分钟内了解 OSI 模型”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202212/16/092612etn6gwaecb91bweg.jpg" alt=""></p><blockquote><p>理解 OSI 框架的基本概念，掌握计算机系统通信机制。</p></blockquote><p><ruby>开放系统互联<rt>Open Systems Interconnection</rt></ruby>（OSI）模型是一个定义计算机、服务器和用户如何在一个系统内通信的标准。它是第一个网络通信标准模型，在上世纪 80 年代早期，所有主流的计算机和通信公司都采用了这个标准。</p><p>OSI 模型提供了一种用于描述网络的通用语言，并以离散的块或层的方式来描述。</p><h3 id="osi-模型的各个层" tabindex="-1">OSI 模型的各个层 <a class="header-anchor" href="#osi-模型的各个层" aria-label="Permalink to “OSI 模型的各个层”">​</a></h3><p>该模型描述了计算机系统通过网络进行通信的七个层。</p><ul><li>7 应用层</li><li>6 表示层</li><li>5 会话层</li><li>4 传输层</li><li>3 网络层</li><li>2 数据链路层</li><li>1 物理层</li></ul><p>每个层都有自己的工作方式和一系列跟其他层不同的协议。本文将逐个剖析这些层级。</p><h3 id="应用层" tabindex="-1">应用层 <a class="header-anchor" href="#应用层" aria-label="Permalink to “应用层”">​</a></h3><p>应用层是在软件中实现的。它是与应用程序交互的层级。</p><p>用发送消息作为例子。发送消息的程序与应用层进行交互，并发送消息。接着，应用层向 OSI 模型的下一个层级（即表示层）发送消息。</p><h3 id="表示层" tabindex="-1">表示层 <a class="header-anchor" href="#表示层" aria-label="Permalink to “表示层”">​</a></h3><p>来自应用层的数据被转发到表示层。表示层接收到文字、字符、字母、数字等形式的数据，并把它们转换为机器可识读的二进制格式数据。这个过程叫做编译。</p><p>在此阶段，ASCII（美国信息交换标准码）字符被转换为扩充的二进制编码的十进制交换码（EBCDIC）。转换后的数据在继续传输前，也会进行编码和加密过程，使用 SSL 协议进行加密和解密。</p><p>表示层的作用是抽象化，它假设下面的层级会处理它们收到的数据。它也负责压缩数据。数据的压缩可能是有损的，也有可能是无损的，这取决于很多因素，这不属于本文的讨论范围。</p><h3 id="会话层" tabindex="-1">会话层 <a class="header-anchor" href="#会话层" aria-label="Permalink to “会话层”">​</a></h3><p>会话层的作用是建立和管理连接。该层级的主要工作是建立会话。例如，你登录网上商城，就在你的机器和服务器之间建立了会话。</p><p>会话层的作用是实现数据的发送和接收，完成后连接的会话就终止了。在一个会话建立前，会进行身份验证。与上一层类似，会话层也假设在它的工作完成后，下面的层级也会准确无误地处理数据。</p><h3 id="传输层" tabindex="-1">传输层 <a class="header-anchor" href="#传输层" aria-label="Permalink to “传输层”">​</a></h3><p>传输层的作用是管理数据传输和其自身的关于数据如何传输的一些协议。从会话层传到这里的数据被分为更小的数据单元，这些数据单元称为片段。这个过程叫做“分段”。每个片段包含来源端口号、目标端口号和一个序列号。端口号用来识别发送数据的应用程序。注意，数据以块的形式传输。序列号用于把这些片段按正确的顺序排列。</p><p>传输层负责控制流量或在给定的时间内传输的数据量。它也负责错误控制，比如数据丢失、损坏等情况。它利用一种错误检测值，通常叫做校验和。传输层对每个数据片段加上校验和，就可以检查所发送的数据是否被正确接收。然后数据传输到网络层。</p><h3 id="网络层" tabindex="-1">网络层 <a class="header-anchor" href="#网络层" aria-label="Permalink to “网络层”">​</a></h3><p>网络层的作用是跟其他网络进行通信。它把从一台机器接收到的数据片段传输给另一台位于不同网络的机器。路由器是作用于网络层的。</p><p>网络层的功能是逻辑寻址（就是确定 IP 地址）。它为发送方和接收方分配 IP 地址，数据包附带了这个地址，就可以被传输到正确的目标机器。接着网络层对数据包进行路由。负载均衡也是在网络层进行的，旨在确保不会发生过载。下一步，数据传输到数据链路层。</p><h3 id="数据链路层" tabindex="-1">数据链路层 <a class="header-anchor" href="#数据链路层" aria-label="Permalink to “数据链路层”">​</a></h3><p>数据链路层支持跟其他设备直接通信。</p><p>它接收到来自网络层、包含发送方和接收方 IP 地址的数据包，进行物理寻址，然后将发送方和接收方的 MAC 地址分配给数据包，形成帧。</p><h3 id="物理层" tabindex="-1">物理层 <a class="header-anchor" href="#物理层" aria-label="Permalink to “物理层”">​</a></h3><p>物理层由系统的所有硬件和物理设备（包括网线、导航系统、适配器等）组成。在这里，从前面层级接收到的数据都是 0 和 1 形式的。物理层把这些数据转换并通过各种方式（如果是光纤电缆，有电线、电信号、光信号；如果是 WIFI，则为无线电信号）传输至本地媒介。</p><p>注意，物理层作用于接收方的一端，把接收到的信号以帧的形式传输到数据链路层（把它转换回二进制数据形式）。然后帧传输到上面的层级，最终应用层（应用软件）会接收到需要的数据。</p><h3 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to “结语”">​</a></h3><p>当你需要描述网络架构或排除网络问题时，OSI 模型的相关知识会对你有所帮助。我希望本文能令你对这个模型的方方面面有清晰的理解。</p><hr>',34)),l("p",null,[e[1]||(e[1]=a("via: ",-1)),i(t,{href:"https://opensource.com/article/22/10/osi-model-network-communications"},{default:r(()=>[...e[0]||(e[0]=[a("https://opensource.com/article/22/10/osi-model-network-communications",-1)])]),_:1})]),l("p",null,[e[6]||(e[6]=a("作者：",-1)),i(t,{href:"https://opensource.com/users/anamika"},{default:r(()=>[...e[2]||(e[2]=[a("Anamika",-1)])]),_:1}),e[7]||(e[7]=a(" 选题：",-1)),i(t,{href:"https://github.com/lkxed"},{default:r(()=>[...e[3]||(e[3]=[a("lkxed",-1)])]),_:1}),e[8]||(e[8]=a(" 译者：",-1)),i(t,{href:"https://github.com/cool-summer-021"},{default:r(()=>[...e[4]||(e[4]=[a("cool-summer-021",-1)])]),_:1}),e[9]||(e[9]=a(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[5]||(e[5]=[a("wxy",-1)])]),_:1})]),l("p",null,[e[12]||(e[12]=a("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[10]||(e[10]=[a("LCTT",-1)])]),_:1}),e[13]||(e[13]=a(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:r(()=>[...e[11]||(e[11]=[a("Linux中国",-1)])]),_:1}),e[14]||(e[14]=a(" 荣誉推出",-1))])])}const C=n(m,[["render",h]]);export{k as __pageData,C as default};
